-- ShubhMart Services marketplace foundation
create table if not exists public.service_providers(id uuid primary key default gen_random_uuid(),user_id uuid unique references auth.users(id) on delete cascade,name text not null,phone text,email text,business_name text,category text,service_area text,status text not null default 'Pending' check(status in ('Pending','Approved','Suspended','Rejected')),kyc_status text not null default 'Pending' check(kyc_status in ('Pending','Submitted','Verified','Rejected')),rating numeric not null default 0 check(rating between 0 and 5),total_completed integer not null default 0 check(total_completed>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.service_providers(id) on delete cascade,name text not null,category text not null,description text,image_url text,price numeric not null check(price>=0),duration_minutes integer not null default 60 check(duration_minutes>0),service_area text,status text not null default 'Pending' check(status in ('Pending','Active','Rejected','Paused')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.service_slots(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.service_providers(id) on delete cascade,service_id uuid not null references public.services(id) on delete cascade,slot_start timestamptz not null,slot_end timestamptz not null,status text not null default 'Available' check(status in ('Available','Booked','Blocked')),created_at timestamptz not null default now(),check(slot_end>slot_start));
create table if not exists public.service_bookings(id uuid primary key default gen_random_uuid(),customer_id uuid not null references auth.users(id) on delete cascade,provider_id uuid not null references public.service_providers(id) on delete restrict,service_id uuid not null references public.services(id) on delete restrict,slot_id uuid unique references public.service_slots(id) on delete set null,booking_status text not null default 'Pending' check(booking_status in ('Pending','Confirmed','Provider Accepted','Scheduled','In Progress','Completed','Cancelled','Rejected','No Show','Disputed','Refunded')),payment_status text not null default 'Pending' check(payment_status in ('Pending','Paid','COD','Refunded')),total_amount numeric not null check(total_amount>=0),address text,customer_note text,provider_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.service_events(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.service_bookings(id) on delete cascade,status text not null,note text,actor_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.service_reviews(id uuid primary key default gen_random_uuid(),booking_id uuid unique not null references public.service_bookings(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,provider_id uuid not null references public.service_providers(id) on delete restrict,rating integer not null check(rating between 1 and 5),review text,created_at timestamptz not null default now());
create index if not exists service_providers_status_category_idx on public.service_providers(status,category);
create index if not exists services_provider_status_idx on public.services(provider_id,status,created_at desc);
create index if not exists services_category_status_idx on public.services(category,status,created_at desc);
create index if not exists service_slots_service_start_idx on public.service_slots(service_id,slot_start,status);
create index if not exists service_slots_provider_idx on public.service_slots(provider_id);
create index if not exists service_bookings_customer_created_idx on public.service_bookings(customer_id,created_at desc);
create index if not exists service_bookings_provider_status_idx on public.service_bookings(provider_id,booking_status,created_at desc);
create index if not exists service_bookings_service_idx on public.service_bookings(service_id);
create index if not exists service_events_booking_created_idx on public.service_events(booking_id,created_at desc);
create index if not exists service_events_actor_idx on public.service_events(actor_user_id);
create index if not exists service_reviews_customer_idx on public.service_reviews(customer_id);
create index if not exists service_reviews_provider_idx on public.service_reviews(provider_id);
alter table public.service_providers enable row level security; alter table public.services enable row level security; alter table public.service_slots enable row level security; alter table public.service_bookings enable row level security; alter table public.service_events enable row level security; alter table public.service_reviews enable row level security;
create policy "public view approved providers" on public.service_providers for select to anon,authenticated using(status='Approved');
create policy "provider read own profile" on public.service_providers for select to authenticated using(user_id=(select auth.uid()));
create policy "provider insert own profile" on public.service_providers for insert to authenticated with check(user_id=(select auth.uid()) and status='Pending' and kyc_status in ('Pending','Submitted'));
create policy "provider update pending profile" on public.service_providers for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and status in ('Pending','Rejected') and kyc_status in ('Pending','Submitted','Rejected'));
create policy "admin manage service providers" on public.service_providers for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "public view active services" on public.services for select to anon,authenticated using(status='Active');
create policy "provider manage own services" on public.services for all to authenticated using(provider_id in(select id from public.service_providers where user_id=(select auth.uid()))) with check(provider_id in(select id from public.service_providers where user_id=(select auth.uid())));
create policy "admin manage services" on public.services for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "public view available slots" on public.service_slots for select to anon,authenticated using(status='Available');
create policy "provider manage own slots" on public.service_slots for all to authenticated using(provider_id in(select id from public.service_providers where user_id=(select auth.uid()))) with check(provider_id in(select id from public.service_providers where user_id=(select auth.uid())));
create policy "admin manage service slots" on public.service_slots for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "customer own bookings" on public.service_bookings for select to authenticated using(customer_id=(select auth.uid()));
create policy "provider own bookings" on public.service_bookings for select to authenticated using(provider_id in(select id from public.service_providers where user_id=(select auth.uid())));
create policy "customer create valid booking" on public.service_bookings for insert to authenticated with check(customer_id=(select auth.uid()) and exists(select 1 from public.services s where s.id=service_bookings.service_id and s.provider_id=service_bookings.provider_id and s.status='Active') and exists(select 1 from public.service_slots sl where sl.id=service_bookings.slot_id and sl.service_id=service_bookings.service_id and sl.provider_id=service_bookings.provider_id and sl.status='Available'));
create policy "customer cancel own booking" on public.service_bookings for update to authenticated using(customer_id=(select auth.uid())) with check(customer_id=(select auth.uid()) and booking_status='Cancelled');
create policy "provider update own bookings" on public.service_bookings for update to authenticated using(provider_id in(select id from public.service_providers where user_id=(select auth.uid()))) with check(provider_id in(select id from public.service_providers where user_id=(select auth.uid())));
create policy "admin manage service bookings" on public.service_bookings for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "customer own events" on public.service_events for select to authenticated using(booking_id in(select id from public.service_bookings where customer_id=(select auth.uid())));
create policy "provider own events" on public.service_events for select to authenticated using(booking_id in(select id from public.service_bookings where provider_id in(select id from public.service_providers where user_id=(select auth.uid()))));
create policy "customer insert own service events" on public.service_events for insert to authenticated with check(actor_user_id=(select auth.uid()) and booking_id in(select id from public.service_bookings where customer_id=(select auth.uid())));
create policy "provider insert own events" on public.service_events for insert to authenticated with check(actor_user_id=(select auth.uid()) and booking_id in(select id from public.service_bookings where provider_id in(select id from public.service_providers where user_id=(select auth.uid()))));
create policy "admin manage service events" on public.service_events for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "customer own reviews" on public.service_reviews for select to authenticated using(customer_id=(select auth.uid()));
create policy "provider reviews" on public.service_reviews for select to authenticated using(provider_id in(select id from public.service_providers where user_id=(select auth.uid())));
create policy "customer completed booking review" on public.service_reviews for insert to authenticated with check(customer_id=(select auth.uid()) and booking_id in(select id from public.service_bookings where customer_id=(select auth.uid()) and booking_status='Completed' and provider_id=service_reviews.provider_id));
create policy "admin manage service reviews" on public.service_reviews for all to authenticated using(private.is_admin()) with check(private.is_admin());